package flickrt

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

func TestRPCBinaryAdditionalCodecLayoutsMatchEffect(t *testing.T) {
	// Encoded-side frames independently generated by Effect 4.1.2.
	cases := []struct {
		name  string
		codec codec
		tree  Value
	}{
		{"flipped structured Json", codecOf(CodecFlip(CodecJsonString(SchemaJsonCodec(CodecWireSchema(CodecEntries(CodecString)))))), Rec("a", "x", "b", "y")},
		{"string record", stringRecord{}, Rec("a", "x", "b", "y")},
		{"entries", codecOf(CodecEntries(SchemaJsonCodec(SchemaNumber))), Rec("a", 1.0, "b", 2.0)},
		{"bool tree true", &stringTree{sch(SchemaBool)}, "true"},
		{"bool tree false", &stringTree{sch(SchemaBool)}, "false"},
		{"bigint tree", &stringTree{sch(SchemaBigint)}, "42"},
		{"record tree", &stringTree{sch(SchemaRecord("s", SchemaString))}, Rec("s", "x")},
	}
	for _, test := range cases {
		t.Run(test.name, func(t *testing.T) {
			node := binCodecLayout(test.codec)
			data, err := binEncode(node, test.tree)
			if err != nil {
				t.Fatal(err)
			}
			expectedHex := rpcBinaryOracle(t, test.name)
			if hex.EncodeToString(data) != expectedHex {
				t.Fatalf("frame %x, want %s", data, expectedHex)
			}
			expected, _ := hex.DecodeString(expectedHex)
			value, err := binDecode(node, expected)
			if err != nil || JsonStringify(value) != JsonStringify(test.tree) {
				t.Fatalf("decode %v, %v", value, err)
			}
		})
	}
	for _, schema := range []Value{SchemaResult(SchemaString, SchemaNumber), SchemaNumber, SchemaInt} {
		var c codec = sch(schema).jsonOf()
		if schema == SchemaNumber || schema == SchemaInt {
			c = &stringTree{sch(schema)}
		}
		if _, err := binEncode(binCodecLayout(c), JsonNull); err == nil {
			t.Fatal("accepted layout Effect rejects")
		}
	}
}

func rpcBinaryOracle(t *testing.T, name string) string {
	t.Helper()
	source, err := os.ReadFile("testdata/rpc_binary.json")
	if err != nil {
		t.Fatal(err)
	}
	var vectors map[string]string
	if err := json.Unmarshal(source, &vectors); err != nil {
		t.Fatal(err)
	}
	if vectors[name] == "" {
		t.Fatalf("missing independent oracle %s", name)
	}
	return vectors[name]
}

func TestRPCBinaryTaggedCodecBlocksMatchEffect(t *testing.T) {
	makeBlock := func(tag string) codec {
		return codecOf(CodecBlock(tag, []Value{"tag", DslField("_tag", CodecLiteral(tag)), "n", DslField("n", SchemaJsonCodec(SchemaNumber))}))
	}
	compiler := newBinCompiler()
	a, b := compiler.codec(makeBlock("A")), compiler.codec(makeBlock("B"))
	for name, layout := range map[string]*binNode{"literal block": a, "tagged codec union": binUnionOf([]*binNode{a, b})} {
		frame, err := binEncode(layout, Rec("_tag", "A", "n", 2.0))
		if err != nil {
			t.Fatal(err)
		}
		if hex.EncodeToString(frame) != rpcBinaryOracle(t, name) {
			t.Fatalf("%s: %x", name, frame)
		}
	}
}
